package com.mytraining;
import android.content.*;import android.database.*;import android.net.Uri;import android.os.*;import android.provider.OpenableColumns;import java.io.*;
public class ShareProvider extends ContentProvider {
public boolean onCreate(){return true;} private File file(Uri u){if(!"/RUOSS-schede.json".equals(u.getPath()))throw new IllegalArgumentException();return new File(getContext().getCacheDir(),"RUOSS-schede.json");}
public String getType(Uri u){return "application/json";}public ParcelFileDescriptor openFile(Uri u,String mode)throws FileNotFoundException{if(!"r".equals(mode))throw new SecurityException();return ParcelFileDescriptor.open(file(u),ParcelFileDescriptor.MODE_READ_ONLY);}
public Cursor query(Uri u,String[] p,String s,String[] a,String sort){File f=file(u);MatrixCursor c=new MatrixCursor(new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE});c.addRow(new Object[]{f.getName(),f.length()});return c;}public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] a){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[] a){throw new UnsupportedOperationException();}}
